<script setup lang="ts">
import {num,pct,frequency,forecastLabel,direction} from '../lib/format'
import type {Forecast} from '../lib/types'
defineProps<{forecasts:Record<string,Forecast>}>()
const names:Record<number,string>={1:'明日 · 1交易日',3:'3日 · 3交易日',7:'7日 · 7交易日',20:'一个月 · 20交易日',60:'3个月 · 60交易日'}
</script><template><div><div class="forecast-grid"><article v-for="h in [1,3,7,20,60]" :key="h" class="forecast-card"><h3>{{names[h]}} · 研究</h3><strong :class="direction(forecasts[h]?.expected_return)">{{forecasts[h]?.expected_return==null||forecasts[h]?.p_up==null?'当前未提供':pct(forecasts[h]?.expected_return)}}</strong><p v-if="forecasts[h]?.p_up!=null" :class="forecasts[h]!.p_up!>=0.5?'bull':'bear'">上涨概率 {{pct(forecasts[h]?.p_up,0).replace('+','')}}</p><p>{{forecastLabel(forecasts[h])}} {{frequency(forecasts[h])}}</p><p>历史收益区间 {{pct(forecasts[h]?.q10)}} ～ {{pct(forecasts[h]?.q90)}}</p><p>样本 {{num(forecasts[h]?.sample_count,0)}} · 基准 {{forecasts[h]?.as_of_date??'尚未计算'}}</p><p>{{forecasts[h]?.explanation??'已有结果保持原模型口径；没有结果时需准备足够历史并计算，不补造预测。'}}</p><small>{{forecasts[h]?.model_version??'无模型快照'}} · 未校准、非收益保证</small></article></div><p class="small-note">周/月K是历史聚合；各期限预测是从同一基准向前看 1/3/7/20/60 个交易日，不是把日预测相加。一个月=20交易日、3个月=60交易日，均为近似。独立样本不足的期限显示「当前未提供」，不插值。</p></div></template>
